'use strict';
// Synthetic records only. These browser controls are not an authorisation layer.
const demoPatients=[
 {id:'DEMO-001',name:'Maya Collins',initials:'MC',time:'09:15',visit:'Community care follow-up',priority:'Discuss sleep and its effect on the working day',source:'I have been keeping a diary.',preference:'Tuesday morning',action:'Review the diary together'},
 {id:'DEMO-002',name:'Alex Taylor',initials:'AT',time:'10:00',visit:'Initial consultation',priority:'Prepare questions for the first appointment',source:'I have written down the questions I want to ask.',preference:'Wednesday afternoon',action:'Review the prepared questions together'},
 {id:'DEMO-003',name:'Sam Wilson',initials:'SW',time:'10:45',visit:'Care plan review',priority:'Check the administrative next steps in the care plan',source:'I have brought a list of the appointments I need to confirm.',preference:'Thursday morning',action:'Review the appointment list together'}
];
const clinicalFields=['consent','captured','note','signed','version','history','formFilled','formReviewed','formData','formApproval','noteTemplate','revision'];
const newPatientRecord=()=>({consent:false,captured:false,note:'',signed:false,version:1,history:[],formFilled:false,formReviewed:false,formData:null,formApproval:null,noteTemplate:'soap',revision:0});
let pendingReview=null;
document.getElementById('dialog').addEventListener('close',()=>{pendingReview=null;});
document.getElementById('dialog').addEventListener('cancel',()=>{pendingReview=null;});
function ensurePatientState(){
 if(!state.patientRecords){const legacy=newPatientRecord();for(const k of clinicalFields)if(state[k]!==undefined)legacy[k]=state[k];state.patientRecords={'DEMO-001':legacy};}
 for(const p of demoPatients)state.patientRecords[p.id]=Object.assign(newPatientRecord(),state.patientRecords[p.id]||{});
 if(!demoPatients.some(p=>p.id===state.selectedPatientId))state.selectedPatientId='DEMO-001';
 if(!Object.getOwnPropertyDescriptor(state,'note')?.get)for(const k of clinicalFields){delete state[k];Object.defineProperty(state,k,{enumerable:false,configurable:true,get(){return this.patientRecords[this.selectedPatientId][k]},set(v){this.patientRecords[this.selectedPatientId][k]=v}});}
}
function currentPatient(){ensurePatientState();return demoPatients.find(p=>p.id===state.selectedPatientId)}
function selectPatient(id){if(!demoPatients.some(p=>p.id===id))return;clearInterval(recordTimer);recording=false;seconds=0;pendingReview=null;closeModal();ensurePatientState();state.selectedPatientId=id;audit('Selected fictional record '+id+'.');render();}
const previousWorkflowRender=render;
render=function(){ensurePatientState();previousWorkflowRender();};
patientStrip=function(){const p=currentPatient();return `<div class="patient-strip"><div class="avatar">${p.initials}</div><div class="meta"><h3>${p.name} <span class="pill grey">Fictional patient</span></h3><p>${p.id} · ${p.visit}</p></div><label class="fine" for="active-patient">Active record<select class="field" id="active-patient" onchange="selectPatient(this.value)">${demoPatients.map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${q.name}</option>`).join('')}</select></label></div>`};
patientPage=function(){const p=currentPatient();return head('Patients & appointments','Three separate fictional records. Notes, consent and forms stay with the selected patient.',`<button class="primary" onclick="nav('C')">Open ${p.name.split(' ')[0]}’s consultation</button>`)+patientStrip()+`<div class="work-grid"><div class="panel"><h2>Today’s appointments</h2>${demoPatients.map(q=>appointment(q.time,q.initials,q.name,q.visit,q.id===p.id)).join('')}<p class="fine">Fictional examples only. No real NHS identifiers are used.</p></div><div class="panel"><h2>${p.name} · context</h2><div class="timeline-item"><small>Patient-stated priority</small><p>${p.priority}</p></div><div class="timeline-item"><small>Scripted source</small><p>${p.source}</p></div><div class="timeline-item"><small>Follow-up preference</small><p>${p.preference}</p></div><button class="wide" onclick="nav('E')">Open pre-appointment briefing →</button></div></div>`};
patientDetail=function(name){const p=demoPatients.find(p=>p.name===name);if(p){selectPatient(p.id);nav('patients');}};
transcriptMarkup=function(){const p=currentPatient();return `<div class="transcript"><time>00:12 · Clinician</time><strong>Dr Jamie Morgan</strong>What would you like us to focus on today?</div><div class="transcript"><time>00:24 · Patient</time><strong>${p.name}</strong>${p.priority}. ${p.source}</div><div class="transcript"><time>01:42 · Clinician</time><strong>Dr Jamie Morgan</strong>We can ${p.action.toLowerCase()} and arrange a follow-up. Which day works for you?</div><div class="transcript"><time>02:08 · Patient</time><strong>${p.name}</strong>${p.preference} would work best.</div><p class="fine">${p.id} · Scripted example, not recorded or transcribed audio.</p>`};
function noteForPatient(type){const p=currentPatient();const identity=p.name+' ('+p.id+')';return type==='soap'?`SUBJECTIVE\n${identity}: ${p.priority}. ${p.source}\n\nOBJECTIVE\nNo objective observations or examination findings supplied.\n\nASSESSMENT\nNo diagnosis or clinical assessment inferred. Clinician review required.\n\nPLAN\n${p.action}. Arrange a follow-up; ${p.preference.toLowerCase()} is the stated preference.`:type==='referral'?`DRAFT REFERRAL — FICTIONAL EXAMPLE\n\nPatient: ${identity}\nReason for referral: [Clinician to specify]\nPatient priority: ${p.priority}.\nRequested action: [Clinician to review and complete]`:type==='summary'?`YOUR APPOINTMENT SUMMARY — FICTIONAL EXAMPLE\n\n${identity}\nYour priority: ${p.priority}.\nNext steps: ${p.action}.\nFollow-up preference: ${p.preference}.\n\nPlease ask your care team if anything is unclear.`:`MDT HANDOVER — FICTIONAL EXAMPLE\n\nPatient: ${identity}\nPatient priority: ${p.priority}.\nAdministrative action: ${p.action}.\nFollow-up preference: ${p.preference}.\nClinical assessment: Not inferred. Clinician input required.`;}
function updateNote(value){if(state.signed)return;state.note=value;state.revision++;pendingReview=null;save();}
draftNote=function(){currentPatient();if(!state.settings.ai)return toast('Enable the AI demo switch to use this scripted example.');if(state.signed)return toast('Create an amendment before changing a signed demo note.');state.noteTemplate='soap';updateNote(noteForPatient('soap'));audit(state.selectedPatientId+': scripted note prepared for review.');nav('N');};
changeTemplate=function(type){if(state.signed||!['soap','referral','summary','mdt'].includes(type))return;state.noteTemplate=type;updateNote(noteForPatient(type));render();};
const previousNotes=notes;
notes=function(){return previousNotes().replace('oninput="state.note=this.value;save()"','oninput="updateNote(this.value)"').replace(`value="${state.noteTemplate}"`,`value="${state.noteTemplate}" selected`);};
reviewNote=function(){if(!state.note.trim()||state.signed)return toast('Add an unsigned draft first.');pendingReview={patientId:state.selectedPatientId,text:state.note,version:state.version,revision:state.revision};modal('Review '+currentPatient().name+' · version '+state.version,`<p>Compare this exact draft with the fictional source. Editing the draft or switching patients cancels this review.</p><pre class="review-copy">${esc(state.note)}</pre><details><summary>Open scripted transcript</summary>${transcriptMarkup()}</details><label class="consent"><input type="checkbox" id="review-confirm"><span>I have checked this draft against its source, including omissions and any edits.</span></label>`,`<button onclick="pendingReview=null;closeModal()">Back to draft</button><button class="primary" onclick="signNote()">Sign demo note</button>`);};
signNote=function(){if(!pendingReview||pendingReview.patientId!==state.selectedPatientId||pendingReview.text!==state.note||pendingReview.version!==state.version||pendingReview.revision!==state.revision||state.signed)return toast('The draft changed or the review expired. Open a fresh review.');if(!document.getElementById('review-confirm')?.checked)return toast('Confirm the review before signing.');state.signed=true;state.history.unshift({patientId:state.selectedPatientId,version:state.version,text:state.note,status:'Signed in demo',at:new Date().toISOString()});pendingReview=null;audit(state.selectedPatientId+': demo note version '+state.version+' reviewed and signed.');closeModal();render();};
amendNote=function(){if(!state.signed)return;pendingReview=null;state.signed=false;state.version++;state.revision++;audit(state.selectedPatientId+': amendment opened as version '+state.version+'.');render();};
exportNote=function(){if(!state.note.trim())return toast('Add a note before exporting.');const p=currentPatient();download(p.id+'-note-v'+state.version+'.txt',`DEEPSYNAPS CLINICAL ADMIN — FICTIONAL DEMO ONLY\nPatient: ${p.name} (${p.id})\nVersion ${state.version} | ${state.signed?'Demo reviewed and signed':'UNSIGNED DRAFT'}\n\n${state.note}`,'text/plain');audit(p.id+': demo note exported.');};
createFollowup=function(){if(!state.signed)return toast('Review and sign the demo note first.');const p=currentPatient();const key=p.id+':followup:v'+state.version;if(!state.tasks.some(t=>t.sourceKey===key)){state.tasks.push({text:`Review ${p.name}’s signed note v${state.version} and arrange follow-up`,patientId:p.id,sourceKey:key,sourceNote:state.note,owner:'Care team',done:false});audit(p.id+': follow-up task linked to signed version '+state.version+'.');}nav('T');};
previewHandoff=function(){if(!state.signed)return;modal('Illustrative handoff payload',`<p>No request is sent. This preview is not a validated EPR payload.</p><pre class="review-copy">${esc(JSON.stringify({demo:true,patientReference:state.selectedPatientId,documentVersion:state.version,review:'demo-signed',destination:'Not connected',submissionStatus:'NOT_SUBMITTED',document:state.note},null,2))}</pre>`);};
evidence=function(){const p=currentPatient();return patientStrip()+`<div class="work-grid"><section class="panel"><h2>Pre-appointment briefing</h2><div class="notice">Fictional ${p.id} record. No external chart or evidence search is connected.</div><div class="timeline-item"><small>Patient-stated priority · scripted 00:24</small><h3>${p.priority}</h3><p>${p.source}</p></div><div class="timeline-item"><small>Preference · scripted 02:08</small><h3>${p.preference}</h3><p>${p.action}.</p></div><div class="timeline-item"><small>Missing information</small><h3>Allergies and medication not supplied</h3><p>Missing information is not treated as “none”.</p></div><button onclick="nav('C')">Open consultation →</button></section><aside class="panel"><h3>Evidence capabilities</h3>${['E01','E03','E04','E07','E09','E10','E11'].map(id=>`<button class="wide" onclick="feature('${id}')">${esc(features.find(f=>f.id===id).title)} ↗</button>`).join('')}</aside></div>`};
function fillForm(){if(state.formApproval)return;const p=currentPatient();state.formData=[{label:'Patient name',value:p.name,original:p.name,source:p.id+' · Fictional patient record',reviewed:false},{label:'Preferred time',value:p.preference,original:p.preference,source:p.id+' · Scripted transcript 02:08',reviewed:false},{label:'Purpose of follow-up',value:p.action,original:p.action,source:p.id+' · Scripted transcript 01:42',reviewed:false}];state.formFilled=true;state.formReviewed=false;state.formApproval=null;audit(p.id+': sample form filled from scripted sources.');render();}
function editFormField(index,value){const f=state.formData?.[index];if(!f||state.formApproval)return;f.value=value;f.reviewed=false;state.formReviewed=false;save();const checkbox=document.getElementById('field-review-'+index);if(checkbox)checkbox.checked=false;const approved=document.getElementById('form-approve');if(approved)approved.disabled=true;}
function reviewFormField(index,checked){if(!state.formData?.[index]||state.formApproval)return;state.formData[index].reviewed=checked;state.formReviewed=state.formData.every(f=>f.reviewed&&f.value.trim());save();render();}
function approveForm(){if(!state.formData||!state.formData.every(f=>f.reviewed&&f.value.trim()))return toast('Review every completed field first.');if(state.formApproval)return;state.formApproval={patientId:state.selectedPatientId,at:new Date().toISOString(),fields:state.formData.map(f=>({...f})),status:'DEMO_APPROVED_NOT_SUBMITTED'};audit(state.selectedPatientId+': form approved locally; nothing submitted.');render();}
function reopenForm(){state.formApproval=null;state.formReviewed=false;state.formData?.forEach(f=>f.reviewed=false);audit(state.selectedPatientId+': form reopened for review.');render();}
function exportForm(){if(!state.formApproval)return toast('Approve the demo form before exporting.');download(state.selectedPatientId+'-demo-form.json',JSON.stringify(state.formApproval,null,2),'application/json');}
forms=function(){const approved=!!state.formApproval;return patientStrip()+`<div class="work-grid"><section class="panel"><div class="panel-head"><h2>Follow-up preference form</h2><span class="pill ${approved?'green':'amber'}">${approved?'Approved locally':'Review required'}</span></div><p class="fine">Inspect the source and review each field. Changes invalidate that field’s review. No patient or EPR submission occurs.</p><button ${approved?'disabled':''} onclick="fillForm()">Fill from sample sources</button>${(state.formData||[]).map((f,i)=>`<div class="form-group"><label for="form-field-${i}">${f.label}</label><input class="field" id="form-field-${i}" value="${esc(f.value)}" ${approved?'readonly':''} oninput="editFormField(${i},this.value)"><details class="field-source"><summary>${f.source}</summary><p>Original source value: ${esc(f.original)}</p><p>Fictional scripted example. Edited values need your review.</p></details><label class="consent"><input type="checkbox" id="field-review-${i}" ${f.reviewed?'checked':''} ${approved?'disabled':''} onchange="reviewFormField(${i},this.checked)"><span>I reviewed this field and any changes.</span></label></div>`).join('')}<div class="actions">${approved?'<button onclick="reopenForm()">Reopen for editing</button><button class="primary" onclick="exportForm()">Export approved demo form</button>':`<button class="primary" id="form-approve" ${!state.formReviewed?'disabled':''} onclick="approveForm()">Approve demo form</button>`}</div></section><aside><div class="panel"><h3>Submission status</h3><p>${approved?'Approved in this browser. Not submitted.':'Awaiting field reviews and local approval.'}</p><p class="fine">Template v1 · Review controls are a workflow simulation, not server-enforced clinical approval.</p></div><div class="panel"><h3>Template & assessment library</h3>${['F01','F03','F04','F05','F09','F10','F11','F12'].map(id=>`<button class="wide" onclick="feature('${id}')">${esc(features.find(f=>f.id===id).title)} ↗</button>`).join('')}</div></aside></div>`};
const priorTour=startTour;
startTour=function(){selectPatient('DEMO-001');priorTour();};
render();
